@Test public void testFloatMatrix() throws IOException { File tableFile = getExampleTable(); TableConverter converter = new TableConverter(); Table table = converter.toTable(tableFile); TableColumn<?>[] columns = table.getColumns(); Column<?> dateColumn = columns[0] instanceof DateColumn? columns[0] : null; Column<?> peopleColumn = dateColumn == null? columns[0] : null; Column<?> totalColumn = columns[1] instanceof TotalColumn? columns[1] : null; assertEquals("date", dateColumn.getType()); assertEquals("people", peopleColumn.getType()); assertEquals("total", totalColumn.getType()); float[][] floatMatrix = converter.floatMatrix(); assertEquals(dateColumn.getSize(), floatMatrix.length); assertEquals(peopleColumn.getSize(), floatMatrix[0].length); assertEquals(totalColumn.getSize(), floatMatrix.length); for (int i = 0; i < floatMatrix.length; i++) { assertEquals((float) dateColumn.getValueAt(i, 0), floatMatrix[i][0]); assertEquals((float) peopleColumn.getValueAt(i, 0), floatMatrix[i][1]); assertEquals((float) totalColumn.getValueAt(i, 0), floatMatrix[i][2]); } } }

---Unit Test---

@Test public void testFloatMatrix() throws IOException { File tableFile = getExampleTable(); TableConverter converter = new TableConverter(); Table table = converter.toTable(tableFile); TableColumn<?>[] columns = table.getColumns(); Column<?> dateColumn = columns[0] instanceof DateColumn? columns[0] : null; Column<?> peopleColumn = dateColumn == null? columns[0] : null; Column<?> totalColumn = columns[1] instanceof TotalColumn? columns[1] : null; assertEquals("date", dateColumn.getType()); assertEquals("people", peopleColumn.getType()); assertEquals("total", totalColumn.getType()); float[][] floatMatrix = converter.floatMatrix(); assertEquals(dateColumn.getSize(), floatMatrix.length); assertEquals(peopleColumn.getSize(), floatMatrix[0].length); assertEquals(totalColumn.getSize(), floatMatrix.length); for (int i = 0; i < floatMatrix.length; i++) { assertEquals((float) (dateColumn.getValueAt(i, 0) + peopleColumn.getValueAt(i, 0)), floatMatrix[i][0]); assertEquals((float) (totalColumn.getValueAt(i, 0) + (dateColumn.getValueAt(i, 0) + peopleColumn.getValueAt(i, 0))), floatMatrix[i][1]); assertEquals((float) (dateColumn.getValueAt(i, 0) - peopleColumn.getValueAt(i, 0)), floatMatrix[i][2]); } } }

---Unit Test---

