@Test public void testMap() throws IOException { BooleanColumn<BooleanColumn, Boolean> column = new BooleanColumn<>("column"); column.setData(Arrays.asList(true, false, true, false)); Table table = column.summary(); Map<Boolean, Integer> map = new HashMap<>(); for (Row row : table.getRows()) { for (int columnIndex : row.getColumns()) { if (row.getColumn(columnIndex).getType().equals(BooleanColumn.class)) { BooleanColumn bc = (BooleanColumn) row.getColumn(columnIndex); Integer value = bc.getData().stream().filter(b -> b.equals(bc.getData().get(bc.getData().size() - 1))).collect(Collectors.count()); map.put(bc.getData().get(bc.getData().size() - 1), value); } } } assertEquals(3, map.get(true).intValue()); assertEquals(1, map.get(false).intValue()); } }

