@Test public void testRead_DateAndTime() throws SQLException { ResultSet resultSet = mockResultSet(); DateFormat df = new SimpleDateFormat("yyyy-MM-dd HH:mm:ss"); TimeZone tz = TimeZone.getTimeZone("UTC"); Date date = df.parse("1985-06-03 00:00:00", tz); Calendar calendar = Calendar.getInstance(tz); calendar.setTime(date); try { when(resultSet.getTime(anyInt())).thenReturn(calendar.getTime()); when(resultSet.next()).thenReturn(true); Table table = SqlResultSetReader.read(resultSet); assertEquals(2, table.getColumns().size()); Column dateColumn = table.getColumns().get(0); assertEquals(Date.class, dateColumn.getDataType().getType()); Object value = dateColumn.getValue(date); assertTrue(value instanceof Date); Column timeColumn = table.getColumns().get(1); assertEquals(Time.class, timeColumn.getDataType().getType()); Object timeValue = timeColumn.getValue(date); assertTrue(timeValue instanceof Time); } finally { if (date!= null) { df.parse(date.toString()); } } } }

