@Test public void testInner() throws Exception { Configuration conf = new Configuration(); conf.setInt(DFS_FAILURE_AUTO_RECOVER, true); final File splitDir = temp.newFolder(); Summary summary = new Summary(splitDir.getAbsolutePath()); MultiSplit split = new MultiSplit(conf, summary, splitDir); final TableLayout layout = new TableLayout(); layout.addColumn("employee_id", Types.INT4); layout.addColumn("name", Types.STRING); layout.addColumn("age", Types.INT4); layout.addColumn("city", Types.STRING); final Table empTable = Table.build(layout, new int[] { 100, 200 }); final Table wageTable = Table.build(layout, new int[] { 100, 200 }); final Table experienceTable = Table.build(layout, new int[] { 100, 200 }); final Table ageTable = Table.build(layout, new int[] { 100, 200 }); final Table cityTable = Table.build(layout, new int[] { 100, 200 }); empTable.append("1", "John", "32", "Paris"); empTable.append("2", "Johnny", "30", "New York"); empTable.append("3", "Johanna", "35", "Santiago"); wageTable.append(100, "100.00", null); wageTable.append(100, "50.00", null); wageTable.append(200, "100.00", null); wageTable.append(200, "50.00", null); experienceTable.append(100, null, null); experienceTable.append(100, "10 years", null); experienceTable.append(200, null, null); experienceTable.append(200, "10 years", null); ageTable.append(30, null, null); ageTable.append(35, null, null); ageTable.append(40, null, null); ageTable.append(45, null, null); cityTable.append(null, "Paris", null); cityTable.append(null, "New York", null); cityTable.append(null, "Santiago", null); Table combined = dataFrameJoiner.inner(empTable, wageTable, experienceTable, ageTable, cityTable); assertEquals(100, combined.size()); assertEquals(100, combined.getColumnWidth(0)); assertEquals(200, combined.getColumnWidth(1)); assertEquals(30, combined.getColumnWidth(2)); assertEquals(40, combined.getColumnWidth(3)); assertEquals(50, combined.getColumnWidth(4)); assertEquals(10, combined.getColumnWidth(5)); } }

