@Test public void testLeftOuter() throws Exception { Configuration conf = new Configuration(); conf.setInt(DFS_FAILURE_MODE, DataFetcherConstants.FailureMode.ALWAYS); final DataFrameJoiner joiner = new DataFrameJoiner(conf); final Table inputTable = CSVFileReader.createTempTable(conf, "abc,def", 1000); final Table inputTable2 = CSVFileReader.createTempTable(conf, "ghi,jkl", 1000); final Table inputTable3 = CSVFileReader.createTempTable(conf, "abd,cde", 1000); final Table eodTable = CSVFileReader.createTempTable(conf, "", 0); final Table combinedTable = joiner.leftOuter(inputTable, inputTable2, inputTable3, eodTable); combinedTable.writeAsText(System.out); assertEquals("abc,def\\nghi,jkl\\nabd,cde", combinedTable.toString()); } }

