@Test public final void testSlicing() { final TableSlice slice1 = new TableSlice(table, 0, 1); assertEquals(2, slice1.columns().size()); assertTrue(slice1.hasColumn("col1")); assertTrue(slice1.hasColumn("col2")); assertEquals(2, slice1.size()); final TableSlice slice2 = new TableSlice(table, 1, 2); assertEquals(2, slice2.columns().size()); assertTrue(slice2.hasColumn("col1")); assertTrue(slice2.hasColumn("col2")); assertEquals(2, slice2.size()); final TableSlice slice3 = new TableSlice(table, 0, 3); assertEquals(3, slice3.columns().size()); assertTrue(slice3.hasColumn("col1")); assertTrue(slice3.hasColumn("col2")); assertTrue(slice3.hasColumn("col3")); assertEquals(3, slice3.size()); assertFalse(slice1.equals(slice3)); assertFalse(slice2.equals(slice3)); } }

