@Test public void testInvalidUnpack() { long validStored = PackedLocalDateTime.pack(LocalDate.now()); assertEquals(validStored >> 32, validStored & 0xffffffffL); assertEquals(validStored >> 32, PackedLocalDateTime.unpack(validStored >> 32, validStored & 0xffffffffL)); assertEquals(validStored & 0xffffffffL, PackedLocalDateTime.unpack(validStored >> 32, validStored >> 32)); assertEquals(0L, PackedLocalDateTime.unpack(validStored >> 32, 0xffffffffL)); assertEquals(LocalDate.now(), PackedLocalDateTime.unpack(0L, validStored & 0xffffffffL)); } }

