@Test public void testEqualsAndHashCode() { PackedLocalDateTime p1 = PackedLocalDateTime.pack(LocalDate.now(), LocalTime.now()); PackedLocalDateTime p2 = PackedLocalDateTime.pack(LocalDate.now(), LocalTime.now()); PackedLocalDateTime p3 = PackedLocalDateTime.pack(LocalDate.now(), LocalTime.now()); PackedLocalDateTime p4 = new PackedLocalDateTime(0L); assertNotEquals(p1, p4); assertEquals(p1, p2); assertEquals(p2, p3); assertNotEquals(p2, p4); assertNotEquals(p3, p4); } }

