@Test public void testIsNotIn() throws Exception { StringColumn column = new StringColumn("col1"); assertEquals(new SelectionBuilder().buildNotIn(new String[]{}).build(), column.isNotIn(new String[]{})); assertEquals(new SelectionBuilder().buildNotIn(new String[]{null}).build(), column.isNotIn(null)); assertEquals(new SelectionBuilder().buildNotIn(new String[]{ ""]).build(), column.isNotIn(new String[]{})); assertEquals(new SelectionBuilder().buildNotIn(new String[]{ "a", "b" }).build(), column.isNotIn(new String[]{ "c", "d" })); assertEquals( new SelectionBuilder().buildNotIn(new String[]{ "a", "b", "c" }).build(), column.isNotIn(new String[]{ "c", "d", "e" })); } }

