@Test public void testLike() throws Exception { StringColumn column = new StringColumn("col1"); assertEquals(new SelectionBuilder().buildLike(null, "", "").build(), column.like(null, "", "")); assertEquals(new SelectionBuilder().buildLike("", null, "%").build(), column.like(null, "", "%")); assertEquals(new SelectionBuilder().buildLike("a", null, "%").build(), column.like(null, "", "%")); assertEquals(new SelectionBuilder().buildLike("", null, "%").build(), column.like(null, "", "%")); assertEquals(new SelectionBuilder().buildLike("a", "a", "%").build(), column.like("", "", "%")); assertEquals(new SelectionBuilder().buildLike("a", null, "%").build(), column.like(null, "", "%")); assertEquals(new SelectionBuilder().buildLike("a", "a", "*").build(), column.like("", "\\*", "")); assertEquals(new SelectionBuilder().buildLike("a", "a", "%").build(), column.like("", "%", "%")); } }

