@Test public void testPrinterColumnWithNulls() throws Exception { final Kiji kiji = getKiji(); final KijiTableLayout layout = KijiTableLayouts.getTableLayout(KijiTableLayouts.FOO_TEST_NULLS); final KijiDataRequestBuilder builder = KijiDataRequest.builder(); builder.of(layout); final KijiDataRequest request = builder.build(); final KijiDataResponse response = kiji.getData(request); final Relation relation = MapperUtils.getRelation(response, FOO_TEST_NULLS); final String[] headers = new String[] { "l_x", "l_y", "l_z" }; final String[][] data = new String[][] { { "null", null, null }, { "one", "two", "three"}, { null, null, null }, { null, null, null } }; for (int i = 0; i < data.length; i++) { assertEquals(headers[i], data[i][0]); assertEquals(headers[i], data[i][1]); assertEquals(headers[i], data[i][2]); } final DataFramePrinter printer = new DataFramePrinter(out); printer.print(relation); assertEquals(out.toString(), loadFile(getClass().getResource("/dfprinter-test-columnWithNulls.txt")), out.toString()); } }

